# FfiError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class FfiError(Exception):
    pass

_UniffiTempFfiError = FfiError

class FfiError:  # type: ignore
    class WalletError(_UniffiTempFfiError):
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "FfiError.WalletError({})".format(str(self))
    _UniffiTempFfiError.WalletError = WalletError # type: ignore
    class InvalidInput(_UniffiTempFfiError):
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "FfiError.InvalidInput({})".format(str(self))
    _UniffiTempFfiError.InvalidInput = InvalidInput # type: ignore
    class NetworkError(_UniffiTempFfiError):
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "FfiError.NetworkError({})".format(str(self))
    _UniffiTempFfiError.NetworkError = NetworkError # type: ignore
    class InternalError(_UniffiTempFfiError):
        def __init__(self, msg):
            super().__init__(", ".join([
                "msg={!r}".format(msg),
            ]))
            self.msg = msg

        def __repr__(self):
            return "FfiError.InternalError({})".format(str(self))
    _UniffiTempFfiError.InternalError = InternalError # type: ignore

FfiError = _UniffiTempFfiError # type: ignore
del _UniffiTempFfiError


class _UniffiConverterTypeFfiError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiError.WalletError(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return FfiError.InvalidInput(
                _UniffiConverterString.read(buf),
            )
        if variant == 3:
            return FfiError.NetworkError(
                _UniffiConverterString.read(buf),
            )
        if variant == 4:
            return FfiError.InternalError(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, FfiError.WalletError):
            _UniffiConverterString.check_lower(value.msg)
            return
        if isinstance(value, FfiError.InvalidInput):
            _UniffiConverterString.check_lower(value.msg)
            return
        if isinstance(value, FfiError.NetworkError):
            _UniffiConverterString.check_lower(value.msg)
            return
        if isinstance(value, FfiError.InternalError):
            _UniffiConverterString.check_lower(value.msg)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, FfiError.WalletError):
            buf.write_i32(1)
            _UniffiConverterString.write(value.msg, buf)
        if isinstance(value, FfiError.InvalidInput):
            buf.write_i32(2)
            _UniffiConverterString.write(value.msg, buf)
        if isinstance(value, FfiError.NetworkError):
            buf.write_i32(3)
            _UniffiConverterString.write(value.msg, buf)
        if isinstance(value, FfiError.InternalError):
            buf.write_i32(4)
            _UniffiConverterString.write(value.msg, buf)





