class FfiSendKind:
    def __init__(self):
        raise RuntimeError("FfiSendKind cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class ONLINE_EXACT:

        def __init__(self,):
            pass

        def __str__(self):
            return "FfiSendKind.ONLINE_EXACT()".format()

        def __eq__(self, other):
            if not other.is_online_exact():
                return False
            return True
    
    class ONLINE_TOLERANCE:
        tolerance: "FfiAmount"

        def __init__(self,tolerance: "FfiAmount"):
            self.tolerance = tolerance

        def __str__(self):
            return "FfiSendKind.ONLINE_TOLERANCE(tolerance={})".format(self.tolerance)

        def __eq__(self, other):
            if not other.is_online_tolerance():
                return False
            if self.tolerance != other.tolerance:
                return False
            return True
    
    class OFFLINE_EXACT:

        def __init__(self,):
            pass

        def __str__(self):
            return "FfiSendKind.OFFLINE_EXACT()".format()

        def __eq__(self, other):
            if not other.is_offline_exact():
                return False
            return True
    
    class OFFLINE_TOLERANCE:
        tolerance: "FfiAmount"

        def __init__(self,tolerance: "FfiAmount"):
            self.tolerance = tolerance

        def __str__(self):
            return "FfiSendKind.OFFLINE_TOLERANCE(tolerance={})".format(self.tolerance)

        def __eq__(self, other):
            if not other.is_offline_tolerance():
                return False
            if self.tolerance != other.tolerance:
                return False
            return True
    
    

    # For each variant, we have an `is_NAME` method for easily checking
    # whether an instance is that variant.
    def is_online_exact(self) -> bool:
        return isinstance(self, FfiSendKind.ONLINE_EXACT)
    def is_online_tolerance(self) -> bool:
        return isinstance(self, FfiSendKind.ONLINE_TOLERANCE)
    def is_offline_exact(self) -> bool:
        return isinstance(self, FfiSendKind.OFFLINE_EXACT)
    def is_offline_tolerance(self) -> bool:
        return isinstance(self, FfiSendKind.OFFLINE_TOLERANCE)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
FfiSendKind.ONLINE_EXACT = type("FfiSendKind.ONLINE_EXACT", (FfiSendKind.ONLINE_EXACT, FfiSendKind,), {})  # type: ignore
FfiSendKind.ONLINE_TOLERANCE = type("FfiSendKind.ONLINE_TOLERANCE", (FfiSendKind.ONLINE_TOLERANCE, FfiSendKind,), {})  # type: ignore
FfiSendKind.OFFLINE_EXACT = type("FfiSendKind.OFFLINE_EXACT", (FfiSendKind.OFFLINE_EXACT, FfiSendKind,), {})  # type: ignore
FfiSendKind.OFFLINE_TOLERANCE = type("FfiSendKind.OFFLINE_TOLERANCE", (FfiSendKind.OFFLINE_TOLERANCE, FfiSendKind,), {})  # type: ignore




class _UniffiConverterTypeFfiSendKind(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiSendKind.ONLINE_EXACT(
            )
        if variant == 2:
            return FfiSendKind.ONLINE_TOLERANCE(
                _UniffiConverterTypeFfiAmount.read(buf),
            )
        if variant == 3:
            return FfiSendKind.OFFLINE_EXACT(
            )
        if variant == 4:
            return FfiSendKind.OFFLINE_TOLERANCE(
                _UniffiConverterTypeFfiAmount.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_online_exact():
            return
        if value.is_online_tolerance():
            _UniffiConverterTypeFfiAmount.check_lower(value.tolerance)
            return
        if value.is_offline_exact():
            return
        if value.is_offline_tolerance():
            _UniffiConverterTypeFfiAmount.check_lower(value.tolerance)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_online_exact():
            buf.write_i32(1)
        if value.is_online_tolerance():
            buf.write_i32(2)
            _UniffiConverterTypeFfiAmount.write(value.tolerance, buf)
        if value.is_offline_exact():
            buf.write_i32(3)
        if value.is_offline_tolerance():
            buf.write_i32(4)
            _UniffiConverterTypeFfiAmount.write(value.tolerance, buf)







